 10	use Application\Interfaces\Admin\AdminAreaInterface;
 11	use Application\Interfaces\Admin\AdminScreenInterface;
 12	use AppUtils\ClassHelper;
 13	use AppUtils\Interfaces\StringableInterface;
 14	use AppUtils\OutputBuffering;
 15	use UI\Page\Navigation\QuickNavigation;
 16	use function AppUtils\parseVariable;
 17	
 18	/**
 19	 * Base class for individual steps in a wizard. Based on the application
 20	 * skeleton for administration pages, this allows for easy form handling
 21	 * and the base structure handles all the data flow and necessary updates.
 22	 *
 23	 * @package Application
 24	 * @subpackage Administration
 25	 * @author Sebastian Mordziol <s.mordziol@mistralys.eu>
 26	 *
 27	 * @see Application_Admin_Wizard
 28	 */
 29	abstract class Application_Admin_Wizard_Step extends Application_Admin_Skeleton
 30	{
 31	    public const int ERROR_CANNOT_UPDATE_FROM_UNMONITORED_STEP = 558002;
 32	    public const int ERROR_UNHANDLED_STEP_UPDATE = 558003;
 33	    public const int ERROR_STEP_MUST_BE_COMPLETE_FOR_OPERATION = 558004;
 34	
 35	    protected Application_Interfaces_Admin_Wizardable $wizard;
 36	    protected int $number;
 37	    protected string $id;
 38	    protected string $instanceID;
 39	    protected bool $updateRequired = false;
 40	
 41	   /**
 42	    * @var array<string,mixed>
 43	    */
 44	    protected ?array $data = null;
 45	
 46	   /**
 47	    * @var string[]
 48	    */
 49	    protected array $monitoredSteps;
 50	
 51	   /**
 52	    * @param Application_Interfaces_Admin_Wizardable $wizard
 53	    * @param int $number
 54	    * @param array<string,mixed> $data
 55	    */
 56	    public function __construct(Application_Interfaces_Admin_Wizardable $wizard, int $number, array $data=array())
 57	    {
 58	        parent::__construct(Application_Driver::getInstance());
 59	
 60	        $this->wizard = $wizard;
 61	        $this->number = $number;
 62	        $this->data = array_merge($this->getDefaultData(), $data);
 63	        $this->instanceID = nextJSID();
 64	        $this->monitoredSteps = $this->getMonitoredSteps();
 65	        $this->id = ClassHelper::getClassTypeName($this);
 66	
 67	        $this->init();
 68	    }
 69	
 70	   /**
 71	    * Called when all steps in the wizard have been
 72	    * initialized, and before the step is processed.
 73	    * Use this to set up the step's environment.
 74	    */
 75	    abstract public function initDone() : void;
 76	
 77	   /**
 78	    * Called right after instantiation of the step class.
 79	    * Used to set up the base environment. Note: the wizard
 80	    * is not finished initializing at this point. Use the
 81	    * {@link preProcess()} method otherwise.
 82	    */
 83	    abstract protected function init() : void;
 84	
 85	   /**
 86	    * Called before the step is processed, used for
 87	    * any initialization routines the step may need.
 88	    * At this time, all steps in the wizard have been
 89	    * initialized and can be accessed.
 90	    */
 91	    abstract protected function preProcess() : void;
 92	
 93	    abstract public function getLabel() : string;
 94	
 95	    /**
 96	     * @return array<string,mixed>
 97	     */
 98	    abstract protected function getDefaultData() : array;
 99	
100	    abstract public function _process() : bool;

101	
102	    abstract public function getAbstract() : string;
103	
104	    /**
105	     * Optional icon for the step.
106	     * @return UI_Icon|NULL
107	     */
108	    public function getIcon() : ?UI_Icon
109	    {
110	        return null;
111	    }
112	
113	    /**
114	     * Retrieves the name of the step, e.g. "StepName".
115	     *
116	     * @return string
117	     */
118	    public function getID() : string
119	    {
120	        return $this->id;
121	    }
122	
123	    public function getTitle() : string
124	    {
125	        return $this->getLabel();
126	    }
127	
128	   /**
129	    * Called before rendering the step's contents. Must return
130	    * a boolean value indicating whether the step has been
131	    * completed, in which case the wizard can jump to the next step.
132	    *
133	    * @return boolean
134	    */
135	    public function process() : bool
136	    {
137	        $this->log('Process | Pre-Process');
138	
139	        $this->preProcess();
140	
141	        $result = $this->_process();
142	
143	        $this->log(sprintf('Process | Processed: [%s].', parseVariable($result)));
144	
145	        // processing was successful
146	        if($result)
147	        {
148	            // The step has not been completed before:
149	            // we set it to complete.
150	            if(!$this->isComplete()) {
151	                $this->setComplete();
152	            }
153	            // the step has been completed before, and
154	            // some data has changed: we need to
155	            // let the other steps adjust to the changes.
156	            else if($this->updateRequired)
157	            {
158	                $this->wizard->handle_stepUpdated($this);
159	            }
160	        }
161	
162	        return $result;
163	    }
164	
165	   /**
166	    * Returns an indexed array with step IDs to monitor
167	    * changes from: if one of these is modified the
168	    * {@link handle_stepUpdated()} method is called.
169	    *
170	    * @return string[]
171	    */
172	    protected function getMonitoredSteps() : array
173	    {
174	        return array();
175	    }
176	
177	    /**
178	     * The URL to switch to this step.
179	     * @param array<string,int|float|string|StringableInterface> $params
180	     * @return string
181	     */
182	    public function getURL(array $params=array()) : string
183	    {
184	        $params['step'] = $this->getID();
185	        return $this->wizard->getURL($params);
186	    }
187	
188	   /**
189	    * The URL to review this step when it has been completed.
190	    * @param array $params
191	    * @return string
192	    */
193	    public function getURLReview(array $params=array()) : string
194	    {
195	        $params['review'] = 'yes';
196	        return $this->getURL($params);
197	    }
198	
199	   /**
200	    * The step number (begins at 1).
201	    * @return int
202	    */
203	    public function getNumber() : int
204	    {
205	        return $this->number;
206	    }
207	
208	   /**
209	    * Whether this is the active step.
210	    * @return boolean
211	    */
212	    public function isActive() : bool
213	    {
214	        return $this->wizard->getActiveStep()->getID() === $this->getID();
215	    }
216	
217	   /**
218	    * Whether this step can be switched to. This is true for
219	    * all steps that have been completed.
220	    *
221	    * @return boolean
222	    */
223	    public function isEnabled() : bool
224	    {
225	        return $this->isComplete();
226	    }
227	
228	   /**
229	    * Checks if this step has been completed.
230	    * @return boolean
231	    */
232	    public function isComplete() : bool
233	    {
234	        return isset($this->data['completed']) && $this->data['completed'] === true;
235	    }
236	
237	   /**
238	    * Sets the completed state of the step.
239	    * @param boolean $complete
240	    * @return $this
241	    */
242	    public function setComplete(bool $complete=true) : self
243	    {
244	        $this->data['completed'] = $complete;
245	        return $this;
246	    }
247	
248	   /**
249	    * Overridden to add the required hidden form variables.
250	    *

249	    * Overridden to add the required hidden form variables.
250	    *
251	    * @see Application_Formable::createFormableForm()
252	    * @inheritDoc
253	    */
254	    public function createFormableForm(string $name, $defaultData = array()) : self
255	    {
256	        parent::createFormableForm($name, $defaultData);
257	
258	        $this->addFormablePageVars();
259	
260	        $this->addHiddenVars(array(
261	            'wizard' => $this->wizard->getSessionID(),
262	            'step' => $this->wizard->getActiveStep()->getID()
263	        ));
264	
265	        return $this;
266	    }
267	
268	   /**
269	    * Retrieves the step's session data collection, which is stored
270	    * by the wizard itself and restored on every request.
271	    *
272	    * @return array<string,mixed>
273	    */
274	    public function getData() : array
275	    {
276	        return $this->data;
277	    }
278	
279	   /**
280	    * Retrieves the URL to cancel the wizard.
281	    *
282	    * @return string
283	    */
284	    protected function getCancelURL() : string
285	    {
286	        return $this->wizard->getCancelURL();
287	    }
288	
289	   /**
290	    * Adds the next/previous buttons to the current formable
291	    * form. Automatically detects where the step is in the
292	    * queue and adjusts the buttons accordingly.
293	    */
294	    protected function injectNavigationButtons() : void
295	    {
296	        $this->requireFormableInitialized();
297	
298	        $this->injectNavigationBack();
299	        $this->injectNavigationPrimary();
300	
301	        $this->formableForm->addLinkButton(
302	            $this->getCancelURL(),
303	            UI::icon()->cancel().' '.t('Cancel'),
304	            t('Cancels the wizard session.')
305	        )
306	        ->addClass('btn-warning')
307	        ->addClass('wizard-cancel');
308	
309	        if($this->user->isDeveloper())
310	        {
311	            $this->formableForm->addDevPrimarySubmit(t('Submit'))
312	            ->addClass('wizard-dev-submit');
313	        }
314	    }
315	
316	    private function injectNavigationPrimary() : void
317	    {
318	        $next = $this->wizard->getNextStep();
319	
320	        if($next)
321	        {
322	            $this->formableForm->addPrimarySubmit(
323	                t('Next').' '.UI::icon()->next(),
324	                'save',
325	                t('Go forward to %1$s.', $next->getLabel())
326	            );
327	
328	            return;
329	        }
330	
331	        $el = $this->formableForm->addPrimarySubmit(
332	            $this->getButtonConfirmIcon().' '.$this->getButtonConfirmLabel(),
333	            'save',
334	            $this->getButtonConfirmTooltip()
335	        );
336	
337	        $el->setAttribute(
338	            'onclick',
339	            sprintf(
340	                "application.showLoader(%s)",
341	                JSHelper::phpVariable2AttributeJS($this->getButtonConfirmLoadingText())
342	            )
343	        );
344	    }
345	
346	    private function injectNavigationBack() : void
347	    {
348	        $prev = $this->wizard->getPreviousStep();
349	
350	        if(!$prev)
351	        {
352	            return;
353	        }
354	
355	        $this->formableForm->addLinkButton(
356	            $prev->getURLReview(),
357	            UI::icon()->previous() . ' ' . t('Back'),
358	            t('Go back one step to %1$s.', $prev->getLabel())
359	        );
360	    }
361	
362	    protected function getButtonConfirmIcon() : UI_Icon
363	    {
364	        return UI::icon()->ok();
365	    }
366	
367	    protected function getButtonConfirmLoadingText() : string
368	    {
369	        return t('Please wait, processing tasks...');
370	    }
371	
372	    protected function getButtonConfirmLabel() : string
373	    {
374	        return t('Confirm');
375	    }
376	
377	    protected function getButtonConfirmTooltip() : string
378	    {
379	        return t('Confirms the wizard session, and executes all planned tasks.');
380	    }
381	
382	   /**
383	    * Sets a data key. This should be used when the step has been submitted,
384	    * as it checks if the data has been modified. If it has been modified,
385	    * all steps will have the occasion to review whether this invalidates
386	    * their own data.
387	    *
388	    * @param string $name
389	    * @param mixed $value
390	    * @return $this
391	    */
392	    protected function setData(string $name, $value): self
393	    {
394	        $old = null;
395	        if(isset($this->data[$name])) {
396	            $old = $this->data[$name];
397	        }

397	        }
398	
399	        // If this step has already been completed previously and
400	        // a data key is modified, an update of the wizard is required.
401	        if(!$this->updateRequired && $old !== $value && $this->isComplete()) {
402	            $this->updateRequired = true;
403	        }
404	
405	        $this->data[$name] = $value;
406	
407	        return $this;
408	    }
409	
410	   /**
411	    * This is called when a step in the wizard has been modified
412	    * that comes before this one. Allows the step to adjust its
413	    * status according to the new data.
414	    *
415	    * @param Application_Admin_Wizard_Step $step
416	    */
417	    public function handle_stepUpdated(Application_Admin_Wizard_Step $step): void
418	    {
419	        if(!$this->isComplete()) {
420	            return;
421	        }
422	
423	        if(!$this->isMonitoring($step)) {
424	            throw new Application_Exception(
425	                'Cannot update from non-monitored step',
426	                sprintf(
427	                    'The step [%s] is not monitored by the [%s] step.',
428	                    $step->getID(),
429	                    $this->getID()
430	                ),
431	                self::ERROR_CANNOT_UPDATE_FROM_UNMONITORED_STEP
432	            );
433	        }
434	
435	        $this->_handle_stepUpdated($step);
436	
437	        if($this->updateRequired) {
438	            $this->wizard->handle_stepUpdated($this);
439	        }
440	    }
441	
442	    public function handle_cancelWizardCleanup() : void
443	    {
444	
445	    }
